using Godot;
using System.Collections.Generic;
public class Attack { public float damage; public bool is_critical = false; public bool is_execution = false; public int hits = 1; public int bounces = 0; public List<Variant> effects = new(); public Source source; public Dictionary<string, Variant> tags = new(); public float crit_chance = 0.0f; public Attack() { } public Attack(float attackDamage, Source attackSource, bool isCritical = false, bool isExecution = false, Dictionary<string, Variant> attackTags = null) { damage = attackDamage; is_critical = isCritical; is_execution = isExecution; source = attackSource; tags = attackTags ?? new Dictionary<string, Variant>(); } }